            continue
        for r in range(h - size + 1):
            for c in range(w - size + 1):
                if all(grid[y][x] != 0
                       for y in range(r, r + size)
                       for x in range(c, c + size)):
                    # Recolor the center cell (odd square) or center 2x2 (even square).
